const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ headless: false });
  const page = await browser.newPage();
  await page.goto('https://search.naver.com/search.naver?query=' + encodeURIComponent('환율'));
  await page.waitForTimeout(2500);

  const text = await page.evaluate(() => document.body.innerText);
  const lines = text.split('\n').map(s => s.trim()).filter(Boolean);
  const idx = lines.findIndex(l => l.includes('환율') || l.includes('미국') || l.includes('USD'));
  console.log('--- 환율 검색결과 발췌 ---');
  console.log(lines.slice(Math.max(0, idx), idx + 40).join('\n'));
})();

